            });
    }

    // The kind check goes first so a caller's predicate only ever sees nodes of the discovery kind
    // and can cast without testing. Null returns the kind check itself, keeping the unfiltered
    // path allocation-free.
    private static Func<SyntaxNode, CancellationToken, bool> WithKindCheck(
        Func<SyntaxNode, CancellationToken, bool> kindCheck,
        Func<SyntaxNode, CancellationToken, bool>? predicate)
    {
        if (predicate is null)
        {
            return kindCheck;
        }

        return (node, cancellationToken) => kindCheck(node, cancellationToken) && predicate(node, cancellationToken);
    }

    private static IncrementalValuesProvider<(TModel Member, TypeModel ContainingType, SyntaxInfo Syntax, EquatableArray<AttributeModel> Attributes)>
        ForMembersWithAttribute<TModel>(
            SyntaxValueProvider provider,
            string fullyQualifiedMetadataName,
            string trackingName,
            Func<SyntaxNode, CancellationToken, bool> kindPredicate,
            Func<SyntaxNode, CancellationToken, bool>? userPredicate,
            bool includeContainingTypeMembers,
            Func<GeneratorAttributeSyntaxContext, bool, CancellationToken, (TModel Member, TypeModel ContainingType, SyntaxInfo Syntax, EquatableArray<AttributeModel> Attributes)?> transform)
    {
        return provider.ForAttributeWithMetadataName(
                fullyQualifiedMetadataName,
                WithKindCheck(kindPredicate, userPredicate),
                (context, cancellationToken) => transform(context, includeContainingTypeMembers, cancellationToken))
            .Where(static item => item is not null)
            .Select(static (item, _) => item!.Value)
            .WithTrackingName(trackingName);
    }

    // definition is the symbol the model and attributes come from: the definition part for a partial
    // member, the target itself otherwise. The implementation part's run drops out when another
    // declaration carries the attribute, since that one is necessarily the definition.
    private static (TModel Member, TypeModel ContainingType, SyntaxInfo Syntax, EquatableArray<AttributeModel> Attributes)?
        TransformMember<TModel>(
            GeneratorAttributeSyntaxContext context,
            ISymbol definition,
            bool isImplementationPart,
            TModel model,
            bool includeContainingTypeMembers,
            CancellationToken cancellationToken)
    {
        var markedAttributes = GetMarkedAttributes(definition, context);

        if (isImplementationPart && HasMarkedDeclarationOtherThan(markedAttributes, context.TargetNode))
        {
            return null;
        }

        var containingType = TypeModel.From(definition.ContainingType, includeContainingTypeMembers, cancellationToken);
        var syntaxInfo = SyntaxInfo.From(context.TargetNode);

        return (model, containingType, syntaxInfo, ToAttributeModels(markedAttributes));
    }

    // context.Attributes only holds the current node's applications; the other parts' come from the
    // symbol, filtered to the same attribute class.
    // OriginalDefinition so Mark<int> and Mark<string> on different parts count as one attribute.
    private static List<AttributeData> GetMarkedAttributes(ISymbol symbol, GeneratorAttributeSyntaxContext context)
    {
        var attributeClass = context.Attributes[0].AttributeClass?.OriginalDefinition;

        return symbol.GetAttributes()
            .Where(attribute => SymbolEqualityComparer.Default.Equals(attribute.AttributeClass?.OriginalDefinition, attributeClass))
            .ToList();
    }

    private static EquatableArray<AttributeModel> ToAttributeModels(List<AttributeData> markedAttributes)
    {
        return markedAttributes
            .Select(AttributeModel.From)
            .OfType<AttributeModel>()
            .ToEquatableArray();
    }

    private static bool HasMarkedDeclarationOtherThan(
        List<AttributeData> markedAttributes,
        SyntaxNode current)
    {
        foreach (var attribute in markedAttributes)
        {
            if (attribute.ApplicationSyntaxReference?.GetSyntax() is AttributeSyntax { Parent.Parent: { } declaration }
                && declaration != current)
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsFirstMarkedDeclaration(
        Compilation compilation,
        List<AttributeData> markedAttributes,
        TypeDeclarationSyntax current)
    {
        SyntaxTree? firstTree = null;
        var firstStart = 0;
        var firstOrdinal = int.MaxValue;

        foreach (var attribute in markedAttributes)
        {
            if (attribute.ApplicationSyntaxReference?.GetSyntax() is not AttributeSyntax { Parent.Parent: TypeDeclarationSyntax declaration })
            {
                continue;
            }

            var ordinal = OrdinalOf(compilation, declaration.SyntaxTree);
            var start = declaration.SpanStart;

            if (ordinal < firstOrdinal || (ordinal == firstOrdinal && start < firstStart))
            {
                firstTree = declaration.SyntaxTree;
                firstStart = start;
                firstOrdinal = ordinal;
            }
        }

        return firstTree is null
            || (firstTree == current.SyntaxTree && firstStart == current.SpanStart);
    }

    private static int OrdinalOf(Compilation compilation, SyntaxTree tree)
    {
        var ordinal = 0;

        foreach (var candidate in compilation.SyntaxTrees)
        {
            if (candidate == tree)
            {
                return ordinal;
            }

            ordinal++;
        }

        return int.MaxValue;
    }

    private static (TypeModel Type, SyntaxInfo Syntax, EquatableArray<AttributeModel> Attributes)? Transform(
        GeneratorAttributeSyntaxContext context,
        bool includeMembers,
        CancellationToken cancellationToken)
    {
        var typeDeclaration = (TypeDeclarationSyntax)context.TargetNode;
        var typeSymbol = (INamedTypeSymbol)context.TargetSymbol;

        var markedAttributes = GetMarkedAttributes(typeSymbol, context);

        if (!IsFirstMarkedDeclaration(context.SemanticModel.Compilation, markedAttributes, typeDeclaration))
        {
            return null;
        }

        var typeModel = TypeModel.From(typeSymbol, includeMembers, cancellationToken);
        var syntaxInfo = SyntaxInfo.From(typeDeclaration);

        return (typeModel, syntaxInfo, ToAttributeModels(markedAttributes));
    }
}
